package dev.gamersclt.batcaverna.nativeapp;
import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,manifest=Config.NONE)
public class HomeResumePolicyTest {
 private JSONObject row(String id,String category,String type,String status,String date)throws Exception{return new JSONObject().put("id",id).put("categoria",category).put("tipo",type).put("status",status).put("updated_at",date);}
 @Test public void combinesCategoriesDeduplicatesAndKeepsOnlyActiveTitles()throws Exception{JSONObject game=row("1","jogos","","🎮 Em Progresso","2026-11-05T10:00:00Z"),anime=row("2","filmes","🍥 Anime","🍿 Maratonando","2026-11-05T09:30:00-01:00"),series=row("3","filmes","📺 Série","📺 Assistindo","bad"),done=row("4","jogos","","✅ Zerado","");JSONArray source=new JSONArray().put(game).put(anime).put(series).put(done).put(game);JSONArray all=HomeResumePolicy.select(source,"all");assertEquals(3,all.length());assertEquals("2",all.getJSONObject(0).getString("id"));assertEquals("3",all.getJSONObject(2).getString("id"));assertEquals(1,HomeResumePolicy.select(source,"animes").length());assertEquals(1,HomeResumePolicy.select(source,"series").length());assertEquals(0,HomeResumePolicy.select(source,"filmes").length());assertEquals(5,source.length());}
 @Test public void boundsEachFilterAfterSortingNotBefore()throws Exception{JSONArray source=new JSONArray();for(int i=0;i<12;i++)source.put(row("g"+i,"jogos","","Jogando","2026-11-05T10:00:00Z"));source.put(row("movie","filmes","Filme","Assistindo","2026-11-06T10:00:00Z"));assertEquals(8,HomeResumePolicy.select(source,"all").length());assertEquals("movie",HomeResumePolicy.select(source,"all").getJSONObject(0).getString("id"));assertEquals(1,HomeResumePolicy.select(source,"filmes").length());}
}
